import {
  DOCUMENTED_OPENAI_MODELS,
  GPT6_PRICING_TERMS,
} from "./model-context-catalog.js";

/** Only bounded, non-secret pricing labels may enter the durable usage ledger. */
export function projectUsagePricingContext(usage = {}) {
  const projected = {};
  for (const [key, alias] of [
    ["service_tier", "serviceTier"],
    ["regional_processing", "regionalProcessing"],
  ]) {
    if (!Object.hasOwn(usage, key) && !Object.hasOwn(usage, alias)) continue;
    if (
      Object.hasOwn(usage, key) &&
      Object.hasOwn(usage, alias) &&
      usage[key] !== usage[alias]
    ) {
      throw new TypeError(`usage pricing aliases conflict: ${key}`);
    }
    const value = Object.hasOwn(usage, key) ? usage[key] : usage[alias];
    if (key === "service_tier") {
      projected[key] =
        typeof value === "string" &&
        Object.hasOwn(GPT6_PRICING_TERMS.serviceMultipliers, value)
          ? value
          : "unknown";
    } else {
      if (typeof value !== "boolean")
        throw new TypeError("usage regional processing must be boolean");
      projected[key] = value;
    }
  }
  return projected;
}

/** Preserve per-request thresholds in a bounded set of aggregate price buckets. */
export function mergeUsagePricingBucket(entry, usage) {
  if (
    String(entry.provider).toLowerCase() !== "openai" ||
    !DOCUMENTED_OPENAI_MODELS[String(entry.model).toLowerCase()]?.pricing
  )
    return;
  const metadata = projectUsagePricingContext(usage);
  const promptTokens =
    usage.requestInputTokens ??
    usage.inputTokens +
      (usage.cacheReadTokens || 0) +
      (usage.cacheCreationTokens || 0);
  const long = promptTokens > GPT6_PRICING_TERMS.longContext.threshold;
  const serviceTier = metadata.service_tier || "standard";
  const regionalProcessing = metadata.regional_processing === true;
  entry.pricingBuckets ||= [];
  let bucket = entry.pricingBuckets.find(
    (item) =>
      item.serviceTier === serviceTier &&
      item.regionalProcessing === regionalProcessing &&
      item.requestInputTokens > GPT6_PRICING_TERMS.longContext.threshold ===
        long,
  );
  if (!bucket) {
    bucket = {
      inputTokens: 0,
      outputTokens: 0,
      cacheReadTokens: 0,
      cacheCreationTokens: 0,
      totalTokens: 0,
      calls: 0,
      serviceTier,
      regionalProcessing,
      requestInputTokens: promptTokens,
    };
    entry.pricingBuckets.push(bucket);
  }
  for (const key of [
    "inputTokens",
    "outputTokens",
    "cacheReadTokens",
    "cacheCreationTokens",
    "totalTokens",
    "calls",
  ]) {
    const value = usage[key] ?? (key === "calls" ? 1 : 0);
    if (
      !Number.isSafeInteger(value) ||
      value < 0 ||
      !Number.isSafeInteger(bucket[key] + value)
    ) {
      throw new TypeError(`invalid pricing bucket ${key}`);
    }
    bucket[key] += value;
  }
}

import { describe, it, expect, afterEach } from "vitest";
import {
  extractUsage,
  aggregateUsage,
  sessionUsage,
  allSessionsUsage,
  _deps,
} from "../../src/lib/session-usage.js";

const usageEvent = (model, input, output) => ({
  type: "token_usage",
  data: { model, usage: { input_tokens: input, output_tokens: output } },
});

describe("session-usage", () => {
  describe("extractUsage", () => {
    it("reads a token_usage event", () => {
      const u = extractUsage({
        type: "token_usage",
        timestamp: 1,
        data: {
          provider: "anthropic",
          model: "claude-opus-4-6",
          usage: { input_tokens: 100, output_tokens: 50 },
        },
      });
      expect(u).toEqual({
        provider: "anthropic",
        model: "claude-opus-4-6",
        inputTokens: 100,
        outputTokens: 50,
        totalTokens: 150,
        cacheReadTokens: 0,
        cacheCreationTokens: 0,
        timestamp: 1,
      });
    });

    it("reads usage embedded in assistant_message", () => {
      const u = extractUsage({
        type: "assistant_message",
        timestamp: 2,
        data: {
          content: "...",
          usage: { prompt_tokens: 40, completion_tokens: 20, total_tokens: 60 },
          model: "gpt-4o",
        },
      });
      expect(u).toMatchObject({
        model: "gpt-4o",
        inputTokens: 40,
        outputTokens: 20,
        totalTokens: 60,
      });
    });

    it("returns null for events without usage", () => {
      expect(extractUsage({ type: "user_message", data: {} })).toBeNull();
      expect(
        extractUsage({ type: "assistant_message", data: { content: "hi" } }),
      ).toBeNull();
    });

    it("returns null for unknown event types", () => {
      expect(
        extractUsage({
          type: "tool_call",
          data: { usage: { input_tokens: 10 } },
        }),
      ).toBeNull();
    });

    it("returns null when all counts are zero", () => {
      expect(
        extractUsage({
          type: "token_usage",
          data: { usage: { input_tokens: 0, output_tokens: 0 } },
        }),
      ).toBeNull();
    });
  });

  describe("aggregateUsage", () => {
    it("rolls up total + per-model", () => {
      const agg = aggregateUsage([
        {
          type: "token_usage",
          data: {
            provider: "anthropic",
            model: "opus",
            usage: { input_tokens: 100, output_tokens: 50 },
          },
        },
        {
          type: "token_usage",
          data: {
            provider: "anthropic",
            model: "opus",
            usage: { input_tokens: 30, output_tokens: 10 },
          },
        },
        {
          type: "token_usage",
          data: {
            provider: "openai",
            model: "gpt-4o",
            usage: { input_tokens: 20, output_tokens: 5 },
          },
        },
      ]);
      expect(agg.total).toEqual({
        inputTokens: 150,
        outputTokens: 65,
        totalTokens: 215,
        cacheReadTokens: 0,
        cacheCreationTokens: 0,
        calls: 3,
      });
      expect(agg.byModel).toHaveLength(2);
      expect(agg.byModel[0]).toMatchObject({
        provider: "anthropic",
        model: "opus",
        inputTokens: 130,
        outputTokens: 60,
        calls: 2,
      });
      expect(agg.byModel[1]).toMatchObject({
        provider: "openai",
        model: "gpt-4o",
        inputTokens: 20,
        outputTokens: 5,
        calls: 1,
      });
    });

    it("ignores events without usage", () => {
      const agg = aggregateUsage([
        { type: "user_message", data: { content: "hi" } },
        { type: "tool_call", data: { tool: "read_file", args: {} } },
      ]);
      expect(agg.total.calls).toBe(0);
      expect(agg.byModel).toEqual([]);
    });

    it("handles empty + nullish input", () => {
      expect(aggregateUsage([]).total.calls).toBe(0);
      expect(aggregateUsage(null).total.calls).toBe(0);
    });

    it("sorts byModel descending by totalTokens", () => {
      const agg = aggregateUsage([
        {
          type: "token_usage",
          data: {
            model: "small",
            usage: { input_tokens: 1, output_tokens: 1 },
          },
        },
        {
          type: "token_usage",
          data: {
            model: "big",
            usage: { input_tokens: 500, output_tokens: 500 },
          },
        },
      ]);
      expect(agg.byModel[0].model).toBe("big");
      expect(agg.byModel[1].model).toBe("small");
    });
  });

  describe("allSessionsUsage (resilient roll-up)", () => {
    const origReadEvents = _deps.readEvents;
    const origListSessions = _deps.listJsonlSessions;
    afterEach(() => {
      _deps.readEvents = origReadEvents;
      _deps.listJsonlSessions = origListSessions;
    });

    it("aggregates across sessions and skips one that fails to read", () => {
      _deps.listJsonlSessions = () => [
        { id: "good-1" },
        { id: "bad" },
        { id: "good-2" },
      ];
      _deps.readEvents = (id) => {
        if (id === "bad") {
          throw Object.assign(new Error("EACCES"), { code: "EACCES" });
        }
        return [usageEvent("opus", 100, 50)];
      };

      const r = allSessionsUsage();
      expect(r.skipped).toBe(1); // the unreadable session didn't abort the rest
      expect(r.sessions).toHaveLength(2); // good-1 + good-2
      expect(r.total.calls).toBe(2);
      expect(r.total.totalTokens).toBe(300); // 2 × (100+50)
      expect(r.byModel[0]).toMatchObject({ model: "opus", calls: 2 });
    });

    it("reports zero skipped when every session reads cleanly", () => {
      _deps.listJsonlSessions = () => [{ id: "a" }, { id: "b" }];
      _deps.readEvents = () => [usageEvent("gpt-4o", 10, 5)];
      const r = allSessionsUsage();
      expect(r.skipped).toBe(0);
      expect(r.sessions).toHaveLength(2);
    });

    it("sessionUsage rolls up a single session via the injected reader", () => {
      _deps.readEvents = () => [
        usageEvent("opus", 100, 50),
        usageEvent("opus", 30, 10),
      ];
      const r = sessionUsage("s1");
      expect(r.sessionId).toBe("s1");
      expect(r.total.calls).toBe(2);
      expect(r.total.inputTokens).toBe(130);
    });
  });
});

import { afterEach, describe, expect, it, vi } from "vitest";
import Database from "better-sqlite3";
import { resolveModelCapabilityProfile } from "../../src/lib/model-capabilities.js";
import {
  estimateCost,
  lookupRate,
  mergePricing,
  priceRollup,
} from "../../src/lib/llm-pricing.js";
import {
  calculateCost,
  recordUsage,
  getUsageStats,
  getCostBreakdown,
} from "../../src/lib/token-tracker.js";
import {
  aggregateUsage,
  allSessionsUsage,
  _deps,
} from "../../src/lib/session-usage.js";
import { CostBudget } from "../../src/lib/cost-budget.js";
import { normalizeOpenAIResponsesResponse } from "../../src/lib/openai-responses.js";
import { projectRuntimeTokenUsage } from "../../src/lib/runtime-usage-ledger.js";
import { projectVerifiedSession } from "../../src/lib/causal-observability.js";
import { SessionResourceBudget } from "../../src/lib/session-resource-budget.js";

afterEach(() => vi.restoreAllMocks());

describe("September model release contracts", () => {
  it("preserves request pricing through durable projection, budget and Eval", () => {
    const records = [200000, 200000, 300000].map((input, index) =>
      projectRuntimeTokenUsage({
        provider: "openai",
        model: "gpt-6-sol",
        callId: `call-${index}`,
        usage: {
          input_tokens: input,
          output_tokens: 1000,
          service_tier: index === 1 ? "flex" : "fast",
          regional_processing: true,
        },
      }),
    );
    const events = [
      {
        type: "session_start",
        timestamp: 1,
        data: {
          observabilityScope: { workspaceId: "w", teamId: "t", policyId: "p" },
        },
      },
      ...records.map((data) => ({ type: "token_usage", data })),
    ];
    const budget = new CostBudget({ limitUsd: 100 });
    for (const record of records) budget.add(record);
    const observed = projectVerifiedSession("session-a", events, {
      headHash: "a".repeat(64),
      eventCount: events.length,
    });
    expect(observed.usage.estimatedUsd).toBeCloseTo(budget.spentUsd, 10);
    expect(priceRollup(aggregateUsage(events)).cost.totalCost).toBeCloseTo(
      budget.spentUsd,
      10,
    );
    expect(observed.usage.byModel[0].pricingBuckets).toHaveLength(3);
    expect(records[0].usage.service_tier).toBe("fast");
    expect(
      projectRuntimeTokenUsage({
        ...records[0],
        usage: {
          ...records[0].usage,
          service_tier: "sensitive arbitrary text",
        },
      }).usage.service_tier,
    ).toBe("unknown");
  });

  it("preserves pricing conditions in crash-recovery settlements", () => {
    const source = new SessionResourceBudget({ maxUsd: 100 });
    const pending = source.beginUsageSettlement({ id: "call-a" });
    source.markUsageUnknown({ callId: pending.id });
    const snapshot = source.snapshot();
    source.dispose();
    const resumed = SessionResourceBudget.restore(snapshot);
    const record = {
      provider: "openai",
      model: "gpt-6-sol",
      usage: {
        input_tokens: 300000,
        output_tokens: 1000,
        service_tier: "fast",
        regional_processing: true,
      },
    };
    try {
      const recovery = resumed.adjudicateRecovery({
        settled: [{ authorityId: pending.authorityId, ...record }],
      });
      const budget = new CostBudget({ limitUsd: 100 });
      budget.add(record);
      expect(recovery.adjudication.spentUsdDelta).toBeCloseTo(
        budget.spentUsd,
        10,
      );
      expect(resumed.cost.spentUsd).toBeCloseTo(budget.spentUsd, 10);
    } finally {
      resumed.dispose();
    }
  });
  it.each(["gpt-6-astra", "gpt-6-sol", "gpt-6-luna"])(
    "resolves %s only at the official endpoint",
    (model) => {
      const profile = resolveModelCapabilityProfile({
        provider: "openai",
        model,
      });
      expect(profile).toMatchObject({
        contextWindowTokens: 1050000,
        advertisedMaxOutputTokens: 128000,
        runtimeProtocol: "openai-responses",
        windowAssumed: false,
        runtimeVerified: false,
      });
      expect(profile.reasoningEfforts).toContain("high");
      for (const baseUrl of [
        "https://gateway.example/v1",
        "https://api.openai.com.evil/v1",
      ]) {
        expect(
          resolveModelCapabilityProfile({ provider: "openai", model, baseUrl }),
        ).toMatchObject({
          windowAssumed: true,
          runtimeProtocol: "chat-completions",
          advertisedMaxOutputTokens: null,
        });
      }
      expect(
        resolveModelCapabilityProfile({
          provider: "openai",
          model: `${model}-future`,
        }).windowAssumed,
      ).toBe(true);
      expect(lookupRate("openai", `${model}-future`)).toBeNull();
    },
  );

  it("resolves Opus 5.5 without changing a custom gateway's assumptions", () => {
    expect(
      resolveModelCapabilityProfile({
        provider: "anthropic",
        model: "claude-opus-5-5",
        baseUrl: "https://api.anthropic.com/v1",
      }),
    ).toMatchObject({
      contextWindowTokens: 1000000,
      windowAssumed: false,
      advertisedMaxOutputTokens: null,
    });
    expect(
      resolveModelCapabilityProfile({
        provider: "anthropic",
        model: "claude-opus-5-5",
        baseUrl: "https://gateway.example/v1",
      }).windowAssumed,
    ).toBe(true);
    expect(lookupRate("anthropic", "claude-opus-5-5")).toMatchObject({
      in: 4,
      out: 20,
    });
    expect(lookupRate("anthropic", "claude-opus-6")).toBeNull();
    expect(lookupRate("anthropic", "claude-opus-10")).toBeNull();
    expect(
      lookupRate(
        "anthropic",
        "claude-opus-10",
        mergePricing({ anthropic: [{ match: "opus", in: 5, out: 25 }] }),
      ),
    ).toMatchObject({ in: 5, out: 25 });
    expect(lookupRate("anthropic", "claude-opus-5-5-custom")).toBeNull();
  });

  it("prices cached tokens and long prompts at the request boundary", () => {
    const base = {
      provider: "openai",
      model: "gpt-6-sol",
      inputTokens: 272000,
      outputTokens: 1000,
    };
    expect(estimateCost(base).totalCost).toBeCloseTo(0.554, 9);
    expect(
      estimateCost({ ...base, inputTokens: 272001 }).totalCost,
    ).toBeCloseTo(1.103004, 9);
    const cached = estimateCost({
      ...base,
      inputTokens: 200000,
      cacheReadTokens: 73000,
    });
    expect(cached.inputCost).toBeCloseTo(0.8, 9);
    expect(cached.cacheReadCost).toBeCloseTo(0.0292, 9);
    expect(cached.outputCost).toBeCloseTo(0.015, 9);
    expect(
      estimateCost({ ...base, serviceTier: "fast" }).totalCost,
    ).toBeCloseTo(1.108, 9);
    expect(
      estimateCost({ ...base, serviceTier: "flex" }).totalCost,
    ).toBeCloseTo(0.277, 9);
    expect(estimateCost({ ...base, serviceTier: "unknown" }).matched).toBe(
      false,
    );
    expect(estimateCost({ ...base, serviceTier: "constructor" }).matched).toBe(
      false,
    );
    const table = mergePricing({
      openai: [{ match: "gpt-6-sol", in: 4, out: 20 }],
    });
    expect(
      estimateCost({ ...base, table, cacheReadTokens: 1 }).cacheReadCost,
    ).toBeCloseTo(0.0000008, 12);
  });

  it("keeps separate request tiers when aggregating one or many sessions", () => {
    const event = (input) => ({
      type: "token_usage",
      data: {
        provider: "openai",
        model: "gpt-6-sol",
        usage: { input_tokens: input, output_tokens: 1000 },
      },
    });
    const events = [event(200000), event(200000), event(300000)];
    const budget = new CostBudget({ limitUsd: 100 });
    for (const event of events) budget.add(event.data);
    const aggregate = aggregateUsage(events);
    expect(aggregate.byModel[0].pricingBuckets).toHaveLength(2);
    expect(priceRollup(aggregate).cost.totalCost).toBeCloseTo(2.035, 9);
    expect(priceRollup(aggregate).cost.totalCost).toBeCloseTo(
      budget.spentUsd,
      9,
    );
    vi.spyOn(_deps, "listJsonlSessions").mockReturnValue([
      { id: "one" },
      { id: "two" },
    ]);
    vi.spyOn(_deps, "readEvents").mockImplementation((id) =>
      id === "one" ? events.slice(0, 2) : events.slice(2),
    );
    expect(priceRollup(allSessionsUsage()).cost.totalCost).toBeCloseTo(
      budget.spentUsd,
      9,
    );
    const { pricingBuckets, ...legacy } = aggregate.byModel[0];
    expect(priceRollup({ byModel: [legacy] }).cost.unpricedCount).toBe(1);
  });

  it("preserves response service tier for budget settlement", () => {
    expect(
      normalizeOpenAIResponsesResponse({
        status: "completed",
        output: [],
        service_tier: "flex",
        usage: { input_tokens: 100, output_tokens: 20 },
      }).usage.service_tier,
    ).toBe("flex");
  });

  it("uses the same prices in the legacy database, preserving unknown as NULL", () => {
    const db = new Database(":memory:");
